      out.write("        if (feedbackEl) feedbackEl.textContent = hintMsg;\r\n");
      out.write("        commentEl.focus();\r\n");
      out.write("        alert(hintMsg);\r\n");
      out.write("        return;\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    var confirmMsg = '';\r\n");
      out.write("    if (action === 'APPROVE') {\r\n");
      out.write("        confirmMsg = 'Bạn có chắc chắn muốn ĐỒNG Ý PHÊ DUYỆT hồ sơ tuyển dụng này ở cấp hiện tại?';\r\n");
      out.write("    } else if (action === 'REQUEST_CHANGES') {\r\n");
      out.write("        confirmMsg = 'Bạn có chắc chắn muốn YÊU CẦU BỔ SUNG thông tin cho hồ sơ tuyển dụng này? (Hồ sơ sẽ được trả về cho Người tạo hoàn thiện)';\r\n");
